fn solve(n: i8, s: Vec<char>) -> i8 {
    // Requires: n must be non-negative and the length of s must be equal to n
    // Ensures: The return value is the count of adjacent equal-character pairs in s
    // Decreases: n, as we will iterate from 0 to n-1
    // Invariant: At the start of each iteration, count is the number of adjacent equal-character pairs found so far
    //            and i is the current index being checked.
    //            0 <= i < n - 1
    //            count >= 0
    //            s.len() == n as usize

    // Initialize a counter for adjacent equal-character pairs
    let mut count = 0;

    // Iterate through the array, checking adjacent characters
    for i in 0..(n - 1) {
        // Assert: i is within bounds
        assert!(0 <= i && i < n - 1);
        
        if s[i as usize] == s[(i + 1) as usize] {
            count += 1;
        }
    }

    // Ensures: The count of adjacent equal-character pairs is returned
    count
}